/**
 * APP-KUSKAT • DICCIONARIO MAESTRO DE VERBOS EN INGLÉS
 *
 * Catálogo integral de verbos Irregulares y Regulares con todas sus formas gramaticales:
 * 1. Forma Base / Infinitivo (Infinitive / V1)
 * 2. Pasado Simple (Past Simple / V2)
 * 3. Participio Pasado (Past Participle / V3)
 * 4. 3ª Persona Singular Presente (He/She/It: -s, -es, -ies)
 * 5. Gerundio / Participio Presente (-ing)
 * 6. Traducción rigurosa al español
 * 7. Clasificación morfológica y fonética de pronunciación (-ed: /t/, /d/, /ɪd/)
 */

export type VerbType = 'irregular' | 'regular';
export type VerbPattern = 'A-A-A' | 'A-B-B' | 'A-B-C' | 'A-B-A' | 'A-A-B' | 'regular';
export type EdPronunciation = '/t/' | '/d/' | '/ɪd/' | 'irregular';

export interface EnglishVerbEntry {
  id: string;
  infinitive: string;
  pastSimple: string;
  pastParticiple: string;
  thirdPersonSingular: string;
  gerund: string;
  spanish: string;
  type: VerbType;
  pattern: VerbPattern;
  phoneticEd: EdPronunciation;
  notes?: string;
}

export interface RegularVerbRule {
  title: string;
  category: 'spelling' | 'pronunciation';
  rule: string;
  explanation: string;
  examples: { base: string; past: string; phonetic?: string; translation: string }[];
}

